//! Qualidades e Defeitos do M20 Book of Secrets, Capítulo Um: Heroic Traits.
//!
//! Físicos, Mentais, Sociais e Sobrenaturais (BoS, pp. 35-96). Texto do livro em data/compendium/merits_flaws/bos/*.en.md e
//! tradução em *.pt.md quando existir; sem tradução, os acessores de
//! `MeritFlawDefinition` caem no inglês. Os Traits que o livro só remete ao
//! M20 (Acute Senses, Language, Berserker, etc.) não se repetem aqui.

use super::super::models::{MeritFlawDefinition, TraitCategory, TraitType};

#[allow(clippy::too_many_arguments)]
const fn bos(
    id: &'static str,
    name: &'static str,
    name_pt: &'static str,
    trait_type: TraitType,
    category: TraitCategory,
    points_str: &'static str,
    points_str_pt: &'static str,
    available_costs: &'static [i32],
    page_ref: &'static str,
    text: &'static str,
    text_pt: &'static str,
) -> MeritFlawDefinition {
    MeritFlawDefinition {
        id,
        name,
        name_pt,
        technocracy_name: None,
        technocracy_name_pt: None,
        trait_type,
        category,
        points_str,
        points_str_pt,
        available_costs,
        page_ref,
        description: text,
        description_pt: text_pt,
        system: "",
        system_pt: "",
    }
}

